class Counter:
    def __init__(self):
        self.value = 0
    def increment(self, step=1):
        self.value += step
        return self.value

def integer_pair(text):
    a,b = text.split(':')
    return (int(a), int(a))

def bounded_push(values, item, limit):
    values.append(item)
    return values[:limit]

def toggle_copy(flags, key):
    flags[key] = not flags.get(key, False)
    return flags

